{"content": "/**
 * The attribute contract shared by the CSS emitter and this runtime.
 *
 * These names are duplicated from `@pantoken/css`'s `scoped` module rather than imported: this
 * package ships to the browser and must not pull the token IR (a megabyte of data URIs) in behind a
 * value import. The pairing is asserted in `tests/contract.test.ts`.
 *
 * @module
 */

/** Attribute that roots a theme scope. */
export const THEME_ATTR = "data-pantoken-theme";
/** Attribute that pins a subtree to a color scheme. */
export const SCHEME_ATTR = "data-pantoken-scheme";
/** Attribute that selects a custom brand color. */
export const COLOR_ATTR = "data-pantoken-color";
/** Attribute marking a scope that ancestor resolution must not cross. */
export const BOUNDARY_ATTR = "data-pantoken-boundary";
/** Attribute carrying the owning instance id, so sibling instances can tell scopes apart. */
export const INSTANCE_ATTR = "data-pantoken-instance";

/** Every attribute that participates in scope resolution. */
export const SCOPE_ATTRS = [
  THEME_ATTR,
  SCHEME_ATTR,
  COLOR_ATTR,
  BOUNDARY_ATTR,
  INSTANCE_ATTR,
] as const;

/** A color scheme a scope can be pinned to. */
export type Scheme = "light" | "dark";

/** The resolvable state of a scope. Every field is optional — an unset field inherits. */
export interface ScopeConfig {
  /** Theme key, e.g. `"rebrand"`. Matched by `[data-pantoken-theme="…"]`. */
  theme?: string;
  /** Pinned color scheme. Omit to follow the OS preference. */
  scheme?: Scheme;
  /** Custom brand color key. */
  color?: string;
  /** Identifier of the pantoken instance that owns this scope. */
  instanceId?: string;
}

/** A {@link ScopeConfig} resolved against the DOM, plus where each part came from. */
export interface ResolvedScope extends ScopeConfig {
  /** The nearest element that declared any scope attribute, or `null` when none did. */
  element: Element | null;
  /** True when resolution stopped at a `data-pantoken-boundary` element. */
  bounded: boolean;
}

/** The default instance id, used when a scope does not name one. */
export const DEFAULT_INSTANCE = "pantoken";

const SCHEMES = new Set<string>(["light", "dark"]);

/** Narrow an arbitrary value to a {@link Scheme}. */
export function isScheme(value: unknown): value is Scheme {
  return typeof value === "string" && SCHEMES.has(value);
}
